begin;
create table public.hr_import_rows(id bigint generated always as identity primary key,batch_id uuid not null references public.hr_import_batches(id),row_number integer not null,employee_code text,normalized_data jsonb not null default '{}'::jsonb,validation_status text not null check(validation_status in('VALID','DUPLICATE','INVALID')),validation_errors text[] not null default '{}',imported_employee_id uuid references public.hr_employees(id),created_at timestamptz not null default now(),unique(batch_id,row_number));
create table public.biometric_import_rows(id bigint generated always as identity primary key,batch_id uuid not null references public.biometric_import_batches(id),row_number integer not null,device_user_id text,punch_time timestamptz,punch_type text,normalized_data jsonb not null default '{}'::jsonb,validation_status text not null check(validation_status in('VALID','DUPLICATE','UNLINKED','INVALID')),validation_errors text[] not null default '{}',raw_log_id bigint references public.biometric_raw_logs(id),created_at timestamptz not null default now(),unique(batch_id,row_number));
alter table public.hr_import_rows enable row level security;alter table public.biometric_import_rows enable row level security;
revoke all on public.hr_import_rows,public.biometric_import_rows from anon,authenticated;grant select on public.hr_import_rows,public.biometric_import_rows to authenticated;
create policy hr_import_rows_read on public.hr_import_rows for select to authenticated using(public.current_finance_role() in('OWNER','HR_MANAGER','HR_OFFICER') and exists(select 1 from public.hr_import_batches b where b.id=batch_id));
create policy biometric_import_rows_read on public.biometric_import_rows for select to authenticated using(public.current_finance_role() in('OWNER','HR_MANAGER','HR_OFFICER') and exists(select 1 from public.biometric_import_batches b where b.id=batch_id));

create or replace function public.hr_preview_employee_import(p_file_name text,p_sha256 text,p_rows jsonb) returns uuid language plpgsql security definer set search_path='public','private','pg_temp' as $$declare bid uuid;r jsonb;i int:=0;code text;name text;state text;errs text[];valid int:=0;dupes int:=0;invalid int:=0;begin if public.current_finance_role() not in('HR_OFFICER','HR_MANAGER') then raise exception 'Not authorized';end if;if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>5000 then raise exception 'Import must contain an array of at most 5000 rows';end if;if p_sha256 is not null and p_sha256!~'^[a-f0-9]{64}$' then raise exception 'Invalid SHA-256';end if;insert into public.hr_import_batches(file_name,sha256,preview_rows,status,created_by)values(left(p_file_name,240),p_sha256,jsonb_array_length(p_rows),'PREVIEW_ONLY',auth.uid())returning id into bid;for r in select value from jsonb_array_elements(p_rows) loop i:=i+1;code:=nullif(btrim(r->>'employee_code'),'');name:=nullif(btrim(r->>'full_name'),'');errs:='{}';if code is null then errs:=array_append(errs,'employee_code required');end if;if name is null then errs:=array_append(errs,'full_name required');end if;if array_length(errs,1)>0 then state:='INVALID';invalid:=invalid+1;elsif exists(select 1 from public.hr_employees e where lower(e.employee_code)=lower(code)) or exists(select 1 from public.hr_import_rows x where x.batch_id=bid and lower(x.employee_code)=lower(code)) then state:='DUPLICATE';dupes:=dupes+1;else state:='VALID';valid:=valid+1;end if;insert into public.hr_import_rows(batch_id,row_number,employee_code,normalized_data,validation_status,validation_errors)values(bid,i,code,r,state,errs);end loop;update public.hr_import_batches set valid_rows=valid,duplicate_rows=dupes,validation_result=jsonb_build_object('invalid_rows',invalid,'validated_server_side',true) where id=bid;perform private.hr_audit('hr_import_batches',bid,'PREVIEW',null,jsonb_build_object('valid',valid,'duplicates',dupes,'invalid',invalid,'sha256',p_sha256));return bid;end$$;
create or replace function public.hr_confirm_employee_import(p_batch uuid) returns integer language plpgsql security definer set search_path='public','private','pg_temp' as $$declare b public.hr_import_batches%rowtype;x record;eid uuid;done int:=0;begin if public.current_finance_role()<>'HR_MANAGER' or not public.is_hr_authority('HR_MANAGER') then raise exception 'Only designated HR Manager can confirm employee import';end if;select * into b from public.hr_import_batches where id=p_batch for update;if not found or b.status<>'PREVIEW_ONLY' then raise exception 'Batch is not available for confirmation';end if;for x in select * from public.hr_import_rows where batch_id=p_batch and validation_status='VALID' order by row_number loop begin insert into public.hr_employees(employee_code,full_name,department,job_title,hire_date,national_id,phone,contract_type,social_insurance_number,experience_years,school_division,status,created_by,updated_by)values(x.employee_code,btrim(x.normalized_data->>'full_name'),nullif(btrim(x.normalized_data->>'department'),''),nullif(btrim(x.normalized_data->>'job_title'),''),nullif(x.normalized_data->>'hire_date','')::date,nullif(btrim(x.normalized_data->>'national_id'),''),nullif(btrim(x.normalized_data->>'phone'),''),nullif(btrim(x.normalized_data->>'contract_type'),''),nullif(btrim(x.normalized_data->>'social_insurance_number'),''),nullif(x.normalized_data->>'experience_years','')::numeric,nullif(btrim(x.normalized_data->>'school_division'),''),'ACTIVE',auth.uid(),auth.uid())returning id into eid;update public.hr_import_rows set imported_employee_id=eid where id=x.id;done:=done+1;exception when unique_violation then update public.hr_import_rows set validation_status='DUPLICATE',validation_errors=array_append(validation_errors,'duplicate at confirmation') where id=x.id;end;end loop;update public.hr_import_batches set status='IMPORTED',valid_rows=done,validation_result=validation_result||jsonb_build_object('confirmed_server_side',true,'confirmed_by',auth.uid(),'confirmed_at',now()) where id=p_batch;perform private.hr_audit('hr_import_batches',p_batch,'CONFIRM',to_jsonb(b),jsonb_build_object('imported',done));return done;end$$;
alter table public.hr_import_batches drop constraint if exists hr_import_batches_status_check;alter table public.hr_import_batches add constraint hr_import_batches_status_check check(status in('PREVIEW_ONLY','IMPORTED','REJECTED'));

create or replace function public.hr_preview_biometric_import(p_device uuid,p_file_name text,p_sha256 text,p_rows jsonb) returns uuid language plpgsql security definer set search_path='public','private','pg_temp' as $$declare bid uuid;r jsonb;i int:=0;uid text;pt timestamptz;state text;errs text[];a int:=0;d int:=0;u int:=0;bad int:=0;begin if public.current_finance_role() not in('HR_OFFICER','HR_MANAGER') then raise exception 'Not authorized';end if;if not exists(select 1 from public.biometric_devices where id=p_device and active) then raise exception 'Active biometric device required';end if;if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>20000 then raise exception 'Import must contain an array of at most 20000 rows';end if;insert into public.biometric_import_batches(file_name,sha256,device_id,status,column_mapping,created_by)values(left(p_file_name,240),p_sha256,p_device,'PREVIEW','{}',auth.uid())returning id into bid;for r in select value from jsonb_array_elements(p_rows) loop i:=i+1;uid:=nullif(btrim(r->>'device_user_id'),'');errs:='{}';begin pt:=(r->>'punch_time')::timestamptz;exception when others then pt:=null;end;if uid is null or pt is null then state:='INVALID';bad:=bad+1;errs:=array['device_user_id and valid punch_time required'];elsif exists(select 1 from public.biometric_raw_logs l where l.device_id=p_device and l.device_user_id=uid and l.punch_time=pt and coalesce(l.punch_type,'')=coalesce(r->>'punch_type','')) then state:='DUPLICATE';d:=d+1;elsif not exists(select 1 from public.biometric_employee_links l where l.device_id=p_device and l.biometric_device_user_id=uid and l.active) then state:='UNLINKED';u:=u+1;else state:='VALID';a:=a+1;end if;insert into public.biometric_import_rows(batch_id,row_number,device_user_id,punch_time,punch_type,normalized_data,validation_status,validation_errors)values(bid,i,uid,pt,nullif(r->>'punch_type',''),r,state,errs);end loop;update public.biometric_import_batches set accepted_count=a,duplicate_count=d,rejected_count=u+bad,validation_result=jsonb_build_object('unlinked',u,'invalid',bad,'validated_server_side',true) where id=bid;perform private.hr_audit('biometric_import_batches',bid,'PREVIEW',null,jsonb_build_object('valid',a,'duplicates',d,'unlinked',u,'invalid',bad));return bid;end$$;
create or replace function public.hr_confirm_biometric_import(p_batch uuid) returns integer language plpgsql security definer set search_path='public','private','pg_temp' as $$declare b public.biometric_import_batches%rowtype;x record;rid bigint;done int:=0;begin if public.current_finance_role()<>'HR_MANAGER' or not public.is_hr_authority('HR_MANAGER') then raise exception 'Only designated HR Manager can confirm biometric import';end if;select * into b from public.biometric_import_batches where id=p_batch for update;if not found or b.status<>'PREVIEW' then raise exception 'Batch is not available for confirmation';end if;for x in select * from public.biometric_import_rows where batch_id=p_batch and validation_status='VALID' order by row_number loop insert into public.biometric_raw_logs(device_id,device_user_id,punch_time,punch_type,source_reference,import_batch_id,raw_payload)values(b.device_id,x.device_user_id,x.punch_time,x.punch_type,b.file_name,b.id,x.normalized_data)on conflict(device_id,device_user_id,punch_time,punch_type) do nothing returning id into rid;if rid is not null then update public.biometric_import_rows set raw_log_id=rid where id=x.id;done:=done+1;end if;rid:=null;end loop;update public.biometric_import_batches set status='CONFIRMED',accepted_count=done,confirmed_at=now(),confirmed_by=auth.uid() where id=b.id;perform private.hr_audit('biometric_import_batches',b.id,'CONFIRM',to_jsonb(b),jsonb_build_object('imported',done));return done;end$$;

revoke all on function public.hr_preview_employee_import(text,text,jsonb),public.hr_confirm_employee_import(uuid),public.hr_preview_biometric_import(uuid,text,text,jsonb),public.hr_confirm_biometric_import(uuid) from public,anon;grant execute on function public.hr_preview_employee_import(text,text,jsonb),public.hr_confirm_employee_import(uuid),public.hr_preview_biometric_import(uuid,text,text,jsonb),public.hr_confirm_biometric_import(uuid) to authenticated;
commit;
